mapper.select:
select date_format(stat_time, #{periodFmt}) as period,
substring(dimension, length(#{dimensionPrefix}) + 1) as dim_value,
'ALL' as dim_value,
sum(case when metric_key = #{m} then metric_value else 0 end) as m${i}
from ai_stat_minute where stat_time >= #{beginTime} and stat_time < #{endTime}
and dimension like concat(#{dimensionPrefix}, '%')
and dimension = 'ALL'
group by period, dim_value order by period, dim_value limit #{limitRows}
